"explanation": "<ruby>答<rt>こた</rt></ruby>えは 3<span class=\"frac\"><span class=\"n\">2</span><span class=\"d\">5</span></span> L です。\n<ruby>仮分数<rt>かぶんすう</rt></ruby>を<ruby>帯分数<rt>たいぶんすう</rt></ruby>になおすときは、<ruby>分子<rt>ぶんし</rt></ruby>を<ruby>分母<rt>ぶんぼ</rt></ruby>でわります。\n17 ÷ 5 = 3 あまり 2 なので、<ruby>整数<rt>せいすう</rt></ruby>の<ruby>部分<rt>ぶぶん</rt></ruby>が 3、<ruby>残<rt>のこ</rt></ruby>った <span class=\"frac\"><span class=\"n\">2</span><span class=\"d\">5</span></span> が<ruby>分数<rt>ぶんすう</rt></ruby>の<ruby>部分<rt>ぶぶん</rt></ruby>になります。\nよって <span class=\"frac\"><span class=\"n\">17</span><span class=\"d\">5</span></span> L は 3<span class=\"frac\"><span class=\"n\">2</span><span class=\"d\">5</span></span> L です。\nわり<ruby>算<rt>ざん</rt></ruby>の<ruby>商<rt>しょう</rt></ruby>とあまりを<ruby>取<rt>と</rt></ruby>りちがえたり、わる<ruby>数<rt>かず</rt></ruby>をそのまま<ruby>整数<rt>せいすう</rt></ruby>の<ruby>部分<rt>ぶぶん</rt></ruby>にしたりしないよう<ruby>気<rt>き</rt></ruby>をつけます。\nポイント: <ruby>商<rt>しょう</rt></ruby>が<ruby>整数<rt>せいすう</rt></ruby>、あまりが<ruby>分子<rt>ぶんし</rt></ruby>になります。"
