"question": "1<ruby>辺<rt>へん</rt></ruby>が 5cm のひし<ruby>形<rt>がた</rt></ruby>を、<ruby>定規<rt>じょうぎ</rt></ruby>とコンパスでかきます。<ruby>頂点<rt>ちょうてん</rt></ruby>の<ruby>位置<rt>いち</rt></ruby>をとるとき、コンパスの<ruby>開<rt>ひら</rt></ruby>きは<ruby>何<rt>なん</rt></ruby> cm にすればよいですか。",
