"unit": "e4_u09",
"topic": "平行四辺形の角",
"level": 2,
"question": "<ruby>図<rt>ず</rt></ruby>は<ruby>平行四辺形<rt>へいこうしへんけい</rt></ruby>です。<ruby>角<rt>かく</rt></ruby>アの<ruby>大<rt>おお</rt></ruby>きさが 115° のとき、<ruby>角<rt>かく</rt></ruby>イの<ruby>大<rt>おお</rt></ruby>きさは<ruby>何<rt>なん</rt></ruby><ruby>度<rt>ど</rt></ruby>ですか。",
