"explanation": "<ruby>答<rt>こた</rt></ruby>えは ひし<ruby>形<rt>がた</rt></ruby> です。\n「あ」は、<ruby>向<rt>む</rt></ruby>かい<ruby>合<rt>あ</rt></ruby>う2<ruby>組<rt>くみ</rt></ruby>の<ruby>辺<rt>へん</rt></ruby>が<ruby>平行<rt>へいこう</rt></ruby>で、4つの<ruby>辺<rt>へん</rt></ruby>の<ruby>長<rt>なが</rt></ruby>さが<ruby>等<rt>ひと</rt></ruby>しく、<ruby>角<rt>かく</rt></ruby>は<ruby>直角<rt>ちょっかく</rt></ruby>ではありません。この3つに<ruby>合<rt>あ</rt></ruby>う<ruby>四角形<rt>しかくけい</rt></ruby>はひし<ruby>形<rt>がた</rt></ruby>です。\n<ruby>正方形<rt>せいほうけい</rt></ruby>なら3つとも ○ になり、<ruby>長方形<rt>ちょうほうけい</rt></ruby>は「い」、<ruby>台形<rt>だいけい</rt></ruby>は「う」に<ruby>当<rt>あ</rt></ruby>てはまります。○のところだけを<ruby>見<rt>み</rt></ruby>ると<ruby>正方形<rt>せいほうけい</rt></ruby>とまちがえやすいので、×のところも<ruby>必<rt>かなら</rt></ruby>ず<ruby>確<rt>たし</rt></ruby>かめます。\nポイント: <ruby>表<rt>ひょう</rt></ruby>の ○ と × を、<ruby>図形<rt>ずけい</rt></ruby>の<ruby>性質<rt>せいしつ</rt></ruby>と1つずつ<ruby>照<rt>て</rt></ruby>らし<ruby>合<rt>あ</rt></ruby>わせます。"
