"topic": "長方形の面積",
"level": 1,
"question": "<ruby>名<rt>な</rt></ruby>ふだ<ruby>用<rt>よう</rt></ruby>のカードは、たてが6cm、<ruby>横<rt>よこ</rt></ruby>が9cmの<ruby>長方形<rt>ちょうほうけい</rt></ruby>です。このカード1まいの<ruby>面積<rt>めんせき</rt></ruby>は<ruby>何<rt>なん</rt></ruby>cm<sup>2</sup>ですか。",
