"level": 1,
"question": "ゆかにはるタイルは、1<ruby>辺<rt>へん</rt></ruby>が9cmの<ruby>正方形<rt>せいほうけい</rt></ruby>です。このタイル1まいの<ruby>面積<rt>めんせき</rt></ruby>は<ruby>何<rt>なん</rt></ruby>cm<sup>2</sup>ですか。",
