"level": 1,
"question": "1<ruby>辺<rt>へん</rt></ruby>が1mの<ruby>正方形<rt>せいほうけい</rt></ruby>の<ruby>面積<rt>めんせき</rt></ruby>を1m<sup>2</sup>といいます。1m<sup>2</sup>は<ruby>何<rt>なん</rt></ruby>cm<sup>2</sup>ですか。",
